            "たとえば、日本語[にほんご]の「木漏[こも]れ日[び]」や「侘[わ]び寂[さ]び」、あるいは「切[せつ]ない」といった言葉[ことば]を思[おも]い浮[う]かべてみよう。これらはいずれも単[たん]なる物理[ぶつり]現象[げんしょう]や単一[たんいつ]の感情[かんじょう]の名称[めいしょう]にとどまらず、移[うつ]ろいゆく自然[しぜん]への繊細[せんさい]な眼差[まなざ]しや無常[むじょう]観[かん]を含[ふく]んだ豊[ゆた]かな文脈[ぶんみゃく]を背負[せお]っている。その一語[いちご]を口[くち]にしただけで、話[はな]し手[て]と聞[き]き手[て]の間[あいだ]には共通[きょうつう]の情景[じょうけい]や気配[けはい]が瞬時[しゅんじ]に立[た]ち上[のぼ]る。\n\n"
